			},
			registeredHandlers: 1,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			d := NewDynamicEnqueueRequest()
			if tt.setup != nil {
				tt.setup(d)
			}
			d.RemoveHandler(tt.args)
